import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[(pname, pkg['id'])] = pkg['resolvedVersion']
    return pkgs

b = extract(baseline)
a = extract(after)
changes = []
unchanged = []
for key in sorted(set(b) | set(a)):
    proj, pkg = key
    bv = b.get(key)
    av = a.get(key)
    if bv != av:
        changes.append((proj, pkg, bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((proj, pkg, av))

print('CHANGES:')
for c in changes: print(f'  {c[0]:20s} {c[1]:40s} {c[2]:10s} -> {c[3]}')
print()
print('UNCHANGED:')
for u in unchanged: print(f'  {u[0]:20s} {u[1]:40s} {u[2]}')
"

